// Extraer datos enviados por el Chatbot Flotante CanisCalm
const body = $json.body || $json;
const userMessage = body.message || '¿Cómo manejo la reactividad?';
const dogName = body.dog_name || 'tu perro';
const breed = body.breed || 'raza canina';

const query = userMessage.toLowerCase();
let reply = '';

if (query.includes('lat') || query.includes('look at that') || query.includes('mirar')) {
  reply = `🤖 [n8n AI]: El método **Look At That (LAT)** para ${dogName} (${breed}):\n\n1. Mantén a ${dogName} a una distancia segura donde vea al detonante sin reaccionar.\n2. En cuanto lo mire, di la palabra puente (*"¡Sí!"*) o usa el clicker.\n3. Entrégale inmediatamente un premio de alto valor.\n4. Repite varias veces hasta que al ver el estímulo, ${dogName} te mire a ti pidiendo su premio.`;
} else if (query.includes('3 segundo') || query.includes('tres segundo')) {
  reply = `🤖 [n8n AI]: La **Regla de los 3 Segundos** para ${dogName}:\n\n• Permite que ${dogName} mire u olfatee un estímulo por máximo 3 segundos.\n• Antes de alcanzar el 3er segundo, llama su atención suavemente y cambia de dirección para romper la fijación visual.`;
} else if (query.includes('premio') || query.includes('comida')) {
  reply = `🤖 [n8n AI]: Premios recomendados para ${dogName}:\n\n• Pollo desmenuzado, salchicha picada o hígado deshidratado.\n• Deben ser pequeños, suaves y fáciles de consumir sin masticar demasiado.`;
} else {
  reply = `🤖 [n8n AI]: Hola, soy el asistente de entrenamiento para ${dogName} (${breed}). Para trabajar la reactividad, mantén siempre distancia de confort, premio por la calma y evita la tensión en la correa. ¿Deseas consultar sobre el método LAT, regla de los 3 segundos o premios?`;
}

return [{ json: { reply } }];
